--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `order_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_number` varchar(50) DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `address_id` bigint unsigned NOT NULL,
  `coupon_id` int unsigned DEFAULT NULL,
  `coupon_code` varchar(50) DEFAULT NULL,
  `coupon_type` enum('collection','user','general','sales','product','routine') DEFAULT NULL,
  `coupon_discount` decimal(10,2) DEFAULT '0.00',
  `review_coupon_id` int DEFAULT NULL,
  `review_coupon_code` varchar(50) DEFAULT NULL,
  `review_coupon_discount` decimal(10,2) DEFAULT '0.00',
  `source_collection_id` int unsigned DEFAULT NULL,
  `shipping_amount` decimal(10,2) DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `payment_method` enum('COD','Prepaid','Card','UPI','Razorpay') NOT NULL,
  `payment_status` enum('Pending','Paid','Failed','Refunded') DEFAULT 'Pending',
  `razorpay_payment_id` varchar(100) DEFAULT NULL,
  `order_status` enum('Processing','Shipped','Delivered','Cancelled') DEFAULT 'Processing',
  `packaging_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = Not Packed, 1 = Packed',
  `consignment_number` varchar(100) DEFAULT NULL,
