--
-- Table structure for table `pending_payments`
--

DROP TABLE IF EXISTS `pending_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pending_payments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `razorpay_order_id` varchar(100) NOT NULL,
  `razorpay_payment_id` varchar(100) DEFAULT NULL,
  `user_id` bigint unsigned NOT NULL,
  `address_id` bigint unsigned NOT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `payment_method` varchar(50) DEFAULT 'Razorpay',
  `coupon_id` int DEFAULT NULL,
  `coupon_code` varchar(100) DEFAULT NULL,
  `coupon_type` varchar(50) DEFAULT NULL,
  `coupon_discount` decimal(10,2) DEFAULT '0.00',
  `review_coupon_id` int DEFAULT NULL,
  `review_coupon_code` varchar(50) DEFAULT NULL,
  `review_coupon_discount` decimal(10,2) DEFAULT '0.00',
  `source_collection_id` int DEFAULT NULL,
  `shipping_amount` decimal(10,2) DEFAULT '0.00',
  `order_items_json` json NOT NULL,
  `status` enum('pending','processing','completed','failed','refunded') DEFAULT 'pending',
  `created_order_id` int DEFAULT NULL,
  `webhook_received` tinyint(1) DEFAULT '0',
  `error_message` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
