INSERT INTO `product_attributes` VALUES (4,13,'Butyrospermum Parkii Butter, Garcinia Indica Seed Butter, Cocos Nucifera Oil (and) Aloe Barbadensis Leaf, Olea Europaea Fruit Oil (and) Santalum Album Wood, Prunus Amygdalus Dulcis Oil, Cera Alba, Cetyl Alcohol, Stearic Acid, Maranta Arundinacea Root Powder, Tocopherol, Parfum (Cosmetic-grade, skin-safe fragrance used in minimal quantity)','','[{\"benefit_title\": \"Deep Moisture\", \"benefit_description\": \"Coconut, olive, and almond oils give long-lasting hydration and softness.\"}, {\"benefit_title\": \"Calms & Soothes Skin\", \"benefit_description\": \"Aloe vera and sandalwood help cool irritation and keep skin feeling relaxed.\"}, {\"benefit_title\": \"Light, Non-Greasy Feel\", \"benefit_description\": \"Arrowroot powder leaves a smooth, fresh finish without any heaviness.\"}]','2025-11-27 05:41:06','2026-02-06 15:27:31'),(5,14,'Aqua (Water), Sodium Cocoyl Isethionate, Decyl Glucoside, Cocamidopropyl Betaine, Vitis Vinifera (Red Wine), Glycerin, Panthenol, Glycol Stearate (and) Stearamide AMP, Polyquaternium-7, Disodium EDTA, Phenoxyethanol (and) Ethylhexylglycerin, Parfum (Fragrance).','','[{\"benefit_title\": \"Strengthens & Protects\", \"benefit_description\": \"Red wine antioxidants help shield your hair from damage and keep it looking healthy and revived.\"}, {\"benefit_title\": \"Soft, Hydrated Hair\", \"benefit_description\": \"Glycerin and panthenol lock in moisture, giving your strands a smooth, nourished feel.\"}, {\"benefit_title\": \"Gentle, Fresh Cleanse\", \"benefit_description\": \"Mild surfactants cleanse without stripping, leaving your hair clean, light, and softly fragrant.\"}]','2025-11-27 05:55:39','2025-11-27 05:55:39'),(6,15,'Sodium Cocoate (Coconut Oil), Sodium Palmate\n(Palm Oil), Sodium Sunflowerseedate (Sunflower\nOil), Sodium Lactate, Caprae Lac ( Goat milk)\nParfum (Fragrance).','','[{\"benefit_title\": \"Deep Hydration\", \"benefit_description\": \"Goat milk and sodium lactate keep the skin moisturised, soft, and smooth after every wash.\"}, {\"benefit_title\": \"Gentle on Skin\", \"benefit_description\": \"Coconut, palm, and sunflower oils cleanse without stripping, making it ideal for sensitive or dry skin.\"}, {\"benefit_title\": \"Nourishes & Soothes\", \"benefit_description\": \"The creamy formula calms the skin, leaving it supple, refreshed, and lightly fragrant.\"}]','2025-11-27 06:10:54','2025-11-27 06:10:54'),(7,16,'Cocos Nucifera (Coconut) Oil, Ricinus Communis (Castor) Seed Oil, Butyrospermum Parkii (Shea) Butter, Cera Alba (Beeswax), Tocopherol (Vitamin E), Flavor (Lip-Safe), Pigment (Lip-Safe), and other skin- conditioning agents.','','[{\"benefit_title\": \"Deep Nourishment\", \"benefit_description\": \"Coconut oil, castor oil, and shea butter hydrate and soften lips from within.\"}, {\"benefit_title\": \"Long-Lasting Protection\", \"benefit_description\": \"Natural beeswax forms a gentle barrier to lock in moisture and guard against dryness.\"}, {\"benefit_title\": \"Smooth, Healthy Look\", \"benefit_description\": \"Vitamin E and skin-conditioning agents keep lips supple, soothed, and naturally glossy.\"}]','2025-11-27 06:14:58','2025-11-27 06:14:58'),(8,17,'Coconut Oil (Sodium Cocoate), Palm Oil (Sodium Palmate), Sunflower Oil (Sodium Sunflowerseedate), Olive Oil (Sodium Olivate), Water (Aqua), Sodium Lactate, White Kaolin Clay (Kaolin), Pink Clay, Activated Charcoal (Charcoal Powder), Fragrance Oil(Parfum)','','[{\"benefit_title\": \"Deep Detox & Purification\", \"benefit_description\": \"Pink clay, kaolin, and activated charcoal draw out dirt, oil, and impurities for clearer skin.\"}, {\"benefit_title\": \"Gentle, Nourishing Cleanse\", \"benefit_description\": \"Coconut, palm, sunflower, and olive oils cleanse without stripping, keeping skin soft and balanced.\"}, {\"benefit_title\": \"Smooths & Refreshes Skin\", \"benefit_description\": \"The clay blend lightly exfoliates, leaving your skin fresh, refined, and naturally glowing.\"}]','2025-11-27 06:33:19','2025-11-27 06:33:19'),(13,22,'Blend of 5+ Nourishing Oils infused with Eclipta Prostrata (Bhringraj), Vetiveria Zizanoides (Vetiver), Linum Usitatissimum (Flaxseed), Allium Cepa (Onion), Rosmarinus Officinalis (Rosemary), Aloe Barbadensis (Aloe Vera), Trigonella Foenum- Graecum (Fenugreek), Lawsonia Inermis (Henna), Melaleuca Alternifolia (Tea Tree) Leaf E.O, and Cedrus Deodara (Cedarwood) E.O, along with many other traditional botanicals.','','[{\"benefit_title\": \"Supports Healthy Hair Growth\", \"benefit_description\": \"Bhringraj, rosemary, onion, and fenugreek work together to strengthen roots and encourage fuller, healthier growth.\"}, {\"benefit_title\": \"Soothes & Balances the Scalp\", \"benefit_description\": \"Aloe vera and henna calm irritation, reduce dryness, and keep the scalp comfortable and nourished.\"}, {\"benefit_title\": \"Purifies & Revitalises\", \"benefit_description\": \"Tea tree and cedarwood help cleanse the scalp, reduce buildup, and leave the hair feeling fresh, strong, and deeply nourished.\"}]','2025-11-28 05:11:10','2025-11-28 05:11:10'),(14,24,'Cocos Nucifera (Coconut) Oil, Ricinus Communis (Castor) Seed Oil, Butyrospermum Parkii (Shea) Butter, Cera Alba (Beeswax), Tocopherol (Vitamin E), Flavor (Lip-Safe), Pigment (Lip-Safe), and other skin- conditioning agents.','','[{\"benefit_title\": \"Deep Nourishment\", \"benefit_description\": \"Coconut oil, castor oil, and shea butter hydrate and soften lips from within.\"}, {\"benefit_title\": \"Long-Lasting Protection\", \"benefit_description\": \"Natural beeswax forms a gentle barrier to lock in moisture and guard against dryness.\"}, {\"benefit_title\": \"Smooth, Healthy Look\", \"benefit_description\": \"Vitamin E and skin-conditioning agents keep lips supple, soothed, and naturally glossy.\"}]','2026-02-06 14:59:18','2026-02-06 14:59:18'),(15,28,'🌿Kuppaimeni (Acalypha indica) – Purifies skin and helps reduce unwanted body hair with regular use.\n\n🌼 Avarampoo (Senna auriculata) – Brightens skin and enhances natural glow.\n\n🌹 Rose Petals – Soothes, hydrates, and refreshes skin.\n\n🌾 Vetiver (Khus) – Cools skin and leaves a refreshing aroma.\n\n🤍 Poolankizhangu – Gently cleanses and leaves skin silky smooth.\n\n✨ Licorice (Athimadhuram) – Brightens skin and promotes an even complexion.\n\n🪵 Sandalwood (Chandan) – Brightens, soothes, and refreshes skin.','','[]','2026-07-15 14:20:47','2026-07-15 14:20:47'),(16,29,'🥥 Shea Butter – Rich in natural fatty acids for deep moisturization.','','[]','2026-07-29 14:47:04','2026-07-29 14:47:04');
