DROP TABLE IF EXISTS `review_coupons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `review_coupons` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `review_id` int NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `product_id` int NOT NULL,
  `coupon_id` int unsigned NOT NULL,
  `coupon_code` varchar(50) NOT NULL,
  `discount_percentage` int NOT NULL COMMENT '10 for text-only, 20 for with images',
  `has_images` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Whether review included images',
  `valid_from` datetime NOT NULL,
  `valid_until` datetime NOT NULL COMMENT '14 days from review submission',
  `is_utilized` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Marked true after order placement',
  `utilized_at` datetime DEFAULT NULL,
  `utilized_order_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_first_review` (`user_id`) COMMENT 'Ensures one coupon per user (first review only)',
  KEY `fk_review_coupons_review` (`review_id`),
  KEY `fk_review_coupons_product` (`product_id`),
  KEY `fk_review_coupons_coupon` (`coupon_id`),
  KEY `idx_utilized` (`is_utilized`),
  KEY `idx_valid_until` (`valid_until`),
  CONSTRAINT `fk_review_coupons_coupon` FOREIGN KEY (`coupon_id`) REFERENCES `coupons` (`coupon_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_review_coupons_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_review_coupons_review` FOREIGN KEY (`review_id`) REFERENCES `reviews` (`review_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_review_coupons_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

